-- Editorial pass over the imported posts, plus two new columns (series and guest author).
-- Paste all of this into the Supabase SQL Editor and press Run. Running it twice is safe.

-- Posts can belong to a series, such as "Weekly Market Inspection".
alter table public.posts
  add column if not exists series text
  check (series is null or char_length(series) <= 80);

-- Posts written by a guest carry their name. Empty means the site's own author.
alter table public.posts
  add column if not exists author text
  check (author is null or char_length(author) <= 80);

update public.posts set
  slug = 'the-power-of-financial-discipline',
  title = 'The Power of Financial Discipline',
  excerpt = 'Financial discipline is not about big, flashy changes. It is the small, steady decisions that compound over time. The habits that have made the biggest difference to my own finances.',
  seo_description = 'Simple habits for financial discipline: tracking spending, avoiding lifestyle creep, clear goals and delayed gratification.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Financial discipline is one of the most underrated skills in achieving financial freedom. It’s not about big, flashy changes; it’s about consistent, small decisions that compound over time. Here’s how developing discipline has transformed my financial journey and how it can do the same for you:","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Why Discipline Matters","type":"text"}]},{"type":"paragraph","content":[{"text":"Financial success doesn’t happen by accident. It’s the result of deliberate choices, like sticking to a budget, resisting impulse purchases, and saving consistently. Discipline ensures you stay on track even when motivation wanes.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Small Habits That Make a Big Difference","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Track Every Dollar","type":"text","marks":[{"type":"bold"}]},{"text":": Knowing where your money is going helps you make informed decisions and avoid wasteful spending.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Avoid Lifestyle Inflation","type":"text","marks":[{"type":"bold"}]},{"text":": As your income grows, resist the urge to upgrade your lifestyle. Instead, direct that extra money toward savings and investments.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Set Clear Goals","type":"text","marks":[{"type":"bold"}]},{"text":": Whether it’s buying a home, retiring early, or travelling the world, having specific goals keeps you focused and motivated.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Delay Gratification","type":"text","marks":[{"type":"bold"}]},{"text":": Practice waiting for larger rewards instead of giving in to instant gratification. For example, saving for a trip instead of charging it to a credit card.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How I Stay Disciplined","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Accountability","type":"text","marks":[{"type":"bold"}]},{"text":": I share my goals with friends and family to stay accountable. Sometimes, just telling someone about your financial plans makes you more likely to stick to them.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Visualising Success","type":"text","marks":[{"type":"bold"}]},{"text":": I regularly review my financial goals and imagine the freedom and security they’ll bring. This keeps me motivated.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rewarding Progress","type":"text","marks":[{"type":"bold"}]},{"text":": I allow myself small, planned rewards when I hit milestones, like reaching a savings goal or paying off a loan.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Final Thoughts","type":"text"}]},{"type":"paragraph","content":[{"text":"Financial discipline is a skill anyone can develop. Start by making small, intentional changes to your habits, and over time, you’ll see the results. Remember, success is built one step at a time, and every disciplined choice brings you closer to your financial goals.","type":"text"}]}]}'::jsonb,
  cover_image_url = '/imported/the-power-of-financial-discipline/1.webp',
  cover_image_alt = 'The Power of Financial Discipline',
  tags = array['Personal Finance']::text[],
  series = null,
  author = null,
  reading_minutes = 1
where slug = 'the-power-of-financial-discipline';

update public.posts set
  slug = 'budgeting-for-beginners',
  title = 'Budgeting for Beginners',
  excerpt = 'A budget is not about saying no to everything fun. It is a plan for your money. The simple process I used to start budgeting, including a free spreadsheet you can copy.',
  seo_description = 'A beginner''s guide to budgeting: track your spending, set categories, pick a tool and stay flexible.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Budgeting used to feel restrictive to me, but now I see it as freedom—freedom to save, invest, and spend on what truly matters. Here’s how I started budgeting and how you can, too:","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Why Budgeting Matters","type":"text"}]},{"type":"paragraph","content":[{"text":"A budget isn’t about saying “no” to everything fun; it’s about having a plan for your money. It ensures you’re in control, rather than wondering where your money went at the end of the month.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"“A budget is telling your money where to go instead of wondering where it went.”","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"– Dave Ramsey","type":"text"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"My Simple Budgeting Process","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Track Your Spending","type":"text","marks":[{"type":"bold"}]},{"text":": For one month, I tracked every dollar I spent to understand where my money was going. This helped me identify unnecessary expenses.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Set Categories","type":"text","marks":[{"type":"bold"}]},{"text":": I divided my spending into categories like rent, groceries, entertainment, and savings. Then I assigned a realistic amount to each category based on my income.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use Tools","type":"text","marks":[{"type":"bold"}]},{"text":": I use a budgeting app to keep things organised. Apps like Mint and YNAB make it easy to track spending and adjust as needed especially for people with diverse expenses. However for the common man, a spreadsheet like this is perfect: ","type":"text"},{"text":"https://docs.google.com/spreadsheets/d/1qC11pdB_S7ZZZxevoHut_JjdlH28BA__wAzg-SroSj4/edit?usp=sharing","type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.google.com/spreadsheets/d/1qC11pdB_S7ZZZxevoHut_JjdlH28BA__wAzg-SroSj4/edit?usp=sharing"}}]}]}]}]},{"type":"paragraph","content":[{"text":"▶ Watch the video on YouTube","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=WhULO7JJB9o"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Staying on Track","type":"text"}]},{"type":"paragraph","content":[{"text":"The key to sticking with a budget is flexibility. Life happens, and some months you’ll overspend. What matters is getting back on track and staying committed to your goals.","type":"text"}]},{"type":"paragraph","content":[{"text":"Budgeting is a skill anyone can learn, and it’s the foundation of financial success. Start today and take the first step toward financial freedom.","type":"text"}]}]}'::jsonb,
  cover_image_url = '/imported/budgeting-for-beginners/1.webp',
  cover_image_alt = 'Budgeting for Beginners',
  tags = array['Personal Finance', 'Beginners']::text[],
  series = null,
  author = null,
  reading_minutes = 1
where slug = 'budgeting-for-beginners';

update public.posts set
  slug = 'journey-into-the-stock-market',
  title = 'Journey into the Stock Market',
  excerpt = 'Investing felt intimidating until I took the first step. How I got started, the platforms I tried in Australia, and the most important lesson: time in the market beats timing the market.',
  seo_description = 'How I started investing in shares in Australia: learning the basics, choosing a platform and starting small with an index fund.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Investing always felt intimidating to me. Stocks, ETFs, mutual funds—it sounded like a language I didn’t understand. But once I took my first step, I realised it’s simpler than it seems.","type":"text"}]},{"type":"paragraph","content":[{"text":"Make sure that before anything you learn about how investing works. Whether it be bonds, stocks, crypto, or even options, having a comprehensive understanding is crucial.","type":"text"}]},{"type":"paragraph","content":[{"text":"Investing without knowledge is worse than gambling.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Why I Started Investing","type":"text"}]},{"type":"paragraph","content":[{"text":"I wanted my money to grow rather than sit idle in a savings account. Investing allows your money to work for you, thanks to the power of compound interest. The earlier you start, the more time your investments have to grow.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How I Got Started","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Research","type":"text","marks":[{"type":"bold"}]},{"text":": I began by learning the basics—what stocks, bonds, and ETFs are—through free resources like Investopedia and YouTube channels. In the useful links section there will be some great resources.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a Platform","type":"text","marks":[{"type":"bold"}]},{"text":": I opened an account on a beginner-friendly platform that offers low fees and easy access to investments. For the Australian consumer, I found Spaceship good for their managed funds, yet bad for their diversity and transaction speed. eToro is good for their diversity, copy trading, low transaction fees but has high currency exchange rates.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Start Small","type":"text","marks":[{"type":"bold"}]},{"text":": My first investment was in an index fund (Vanguard S&P 500 growth ETF), which spreads risk across a variety of companies. Starting with small amounts helped me build confidence.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"▶ Watch the video on YouTube","type":"text","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=8Ij7A1VCB7I"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Key Lesson","type":"text"}]},{"type":"paragraph","content":[{"text":"Investing isn’t about timing the market—it’s about time ","type":"text"},{"text":"in","type":"text","marks":[{"type":"italic"}]},{"text":" the market. Consistent contributions, even small ones, can grow significantly over time. If I can do it, so can you.","type":"text"}]}]}'::jsonb,
  cover_image_url = '/imported/journey-into-the-stock-market/1.webp',
  cover_image_alt = 'Journey into the Stock Market',
  tags = array['Beginners']::text[],
  series = null,
  author = null,
  reading_minutes = 1
where slug = 'journey-into-the-stock-market';

update public.posts set
  slug = 'assets-vs-liabilities',
  title = 'Assets vs Liabilities',
  excerpt = 'Assets put money in your pocket and liabilities take it out. Understanding the difference is one of the simplest ways to start building wealth.',
  seo_description = 'The difference between assets and liabilities, explained simply, and why it matters for growing your net worth.',
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"When I first heard the terms “assets” and “liabilities,” they sounded like complicated accounting jargon. But understanding these concepts is crucial for building wealth.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What Are Assets and Liabilities?","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assets","type":"text","marks":[{"type":"bold"}]},{"text":": Things that put money in your pocket. Examples include stocks, rental properties, and even a profitable side hustle.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Liabilities","type":"text","marks":[{"type":"bold"}]},{"text":": Things that take money out of your pocket. Examples include credit card debt, car loans, and anything that depreciates in value over time.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Why This Distinction Matters","type":"text"}]},{"type":"paragraph","content":[{"text":"Focusing on acquiring assets while minimising liabilities is the key to growing your net worth. For example, buying a rental property can generate passive income, while purchasing a luxury car often results in ongoing expenses.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"“Do not save what is left after spending, but spend what is left after saving.”","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"– Warren Buffett","type":"text"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"My Journey","type":"text"}]},{"type":"paragraph","content":[{"text":"When I started tracking my finances, I realised I had more liabilities than assets. Slowly but surely, I’m building a portfolio of assets that work for me.","type":"text"}]},{"type":"paragraph","content":[{"text":"The takeaway? Prioritise assets and be mindful of how liabilities can hold you back. Small shifts in focus can have a big impact over time.","type":"text"}]}]}'::jsonb,
  cover_image_url = '/imported/assets-vs-liabilities/1.webp',
  cover_image_alt = 'Assets vs Liabilities',
  tags = array['Personal Finance', 'Beginners']::text[],
  series = null,
  author = null,
  reading_minutes = 1
where slug = 'assets-vs-liabilities';

