update public.posts set
  slug = 'novo-nordisk-vs-eli-lilly-why-the-consensus-has-it-backwards-again',
  title = 'Novo Nordisk vs Eli Lilly: Why the Consensus Has It Backwards, Again',
  excerpt = 'When Eli Lilly''s weight-loss pill hit its trial target, Novo Nordisk shares fell 7%. A closer look at the data shows Novo a year ahead with stronger results, and I am happy to add to my position.',
  seo_description = 'Novo Nordisk''s oral semaglutide against Eli Lilly''s orforglipron: trial results, timelines and why the market read it wrong.',
  content = '{"type":"doc","content":[{"type":"stockSnapshot","attrs":{"company":"Novo Nordisk","ticker":"NVO","exchange":"NYSE","verdict":"buy","currency":"USD","summary":"A year ahead in the race for the weight-loss pill, with stronger numbers.","metrics":[{"label":"P/E when I bought","value":"29x"},{"label":"Pill weight loss (trial)","value":"12.9–16.6%"}],"price":"62.62"}},{"type":"paragraph","content":[{"text":"Last week’s headlines were almost gleeful: ","type":"text"},{"text":"Eli Lilly’s new oral weight-loss pill, orforglipron, hits Phase 3 target","type":"text","marks":[{"type":"bold"}]},{"text":". Novo Nordisk’s share price promptly fell 7 per cent, as if the Danish titan had finally been out-flanked.","type":"text"}]},{"type":"paragraph","content":[{"text":"Hold on.","type":"text","marks":[{"type":"bold"}]}]},{"type":"image","attrs":{"src":"/imported/novo-nordisk-vs-eli-lilly-why-the-consensus-has-it-backwards-again/1.webp","alt":"The four phases of a clinical trial, from 20 to 100 patients in phase 1 to post-marketing studies in phase 4","caption":""}},{"type":"paragraph","content":[{"text":"A quick read of the clinical timelines tells a very different story. Novo Nordisk is already ","type":"text"},{"text":"a full year ahead","type":"text","marks":[{"type":"bold"}]},{"text":" in the race for an effective, convenient weight-loss tablet — and its candidate, oral semaglutide, is posting stronger numbers.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"The state of play in tablets:","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/novo-nordisk-vs-eli-lilly-why-the-consensus-has-it-backwards-again/1.webp","caption":""}},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Novo Nordisk – oral semaglutide 25 mg","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Eli Lilly – orforglipron 36 mg","type":"text","marks":[{"type":"bold"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Average weight loss","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"12.9 – 16.6 %","type":"text","marks":[{"type":"bold"}]},{"text":" (Phase 3 OASIS-4)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"7.9 %","type":"text","marks":[{"type":"bold"}]},{"text":" (latest Phase 3)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Cardiovascular benefit","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Yes","type":"text","marks":[{"type":"bold"}]},{"text":" — 14 % cut in major events (SOUL trial)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"None yet shown","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Regulatory timetable","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Filing to the US FDA ","type":"text"},{"text":"Q1 2025","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Filing ","type":"text"},{"text":"late 2025 / early 2026","type":"text","marks":[{"type":"bold"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Media buzz","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Quiet","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Loud","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"The real surprise? Novo has been refining oral semaglutide since 2019, when the low-dose version (7 mg / 14 mg) won approval as the diabetes drug ","type":"text"},{"text":"Rybelsus","type":"text","marks":[{"type":"bold"}]},{"text":". Higher doses are now locked in for weight management:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"15 % loss","type":"text","marks":[{"type":"bold"}]},{"text":" at 50 mg (OASIS-1, 2023)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"13 – 17 % loss","type":"text","marks":[{"type":"bold"}]},{"text":" at 25 mg with milder nausea (OASIS-4, 2024)","type":"text"}]}]}]},{"type":"image","attrs":{"alt":"","src":"/imported/novo-nordisk-vs-eli-lilly-why-the-consensus-has-it-backwards-again/2.webp","caption":""}},{"type":"paragraph","content":[{"text":"Cardiovascular protection is the kicker. The SOUL study showed a ","type":"text"},{"text":"14 %","type":"text","marks":[{"type":"bold"}]},{"text":" reduction in heart attacks and strokes — a data point Lilly doesn’t yet have.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rapidly expanding pie, not a shrinking slice","type":"text"}]},{"type":"paragraph","content":[{"text":"Since 2023 the obesity-drug market has ballooned ","type":"text"},{"text":"131 % year-on-year","type":"text","marks":[{"type":"bold"}]},{"text":". Novo’s share has slipped from a monopoly to roughly two-thirds, thanks to Lilly’s injectable ","type":"text"},{"text":"Zepbound","type":"text","marks":[{"type":"bold"}]},{"text":", yet Novo still grew its own sales ","type":"text"},{"text":"66 %","type":"text","marks":[{"type":"bold"}]},{"text":" over the same period. With an estimated ","type":"text"},{"text":"800 million","type":"text","marks":[{"type":"bold"}]},{"text":" people worldwide living with obesity or diabetes, this market is nowhere near saturation.","type":"text"}]},{"type":"paragraph","content":[{"text":"Novo isn’t diversifying away; it’s doubling down:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Massive US capacity build-out","type":"text","marks":[{"type":"bold"}]},{"text":" to end supply bottlenecks.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Targeted acquisitions","type":"text","marks":[{"type":"bold"}]},{"text":" that add manufacturing scale, not new therapeutic gambles.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A deep pipeline — including ","type":"text"},{"text":"Amycretin","type":"text","marks":[{"type":"bold"}]},{"text":" (oral, Phase 2) and ","type":"text"},{"text":"CagriSema","type":"text","marks":[{"type":"bold"}]},{"text":" (injectable combo) — ready to slot in as semaglutide eventually goes generic.","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"What about the “other” competitors?","type":"text"}]},{"type":"paragraph","content":[{"text":"Amgen, Roche, Viking Therapeutics and Structure Therapeutics each have candidates in early-stage trials, but none will reach the market before the early 2030s. For the foreseeable future, ","type":"text"},{"text":"Novo Nordisk and Eli Lilly remain a comfortable duopoly","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Valuation checkpoint","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/novo-nordisk-vs-eli-lilly-why-the-consensus-has-it-backwards-again/3.webp","caption":""}},{"type":"paragraph","content":[{"text":"Back in March or February I called Novo “quality at a fair price” on 29× earnings and picked up a starter parcel. After the sell-off the shares trade on:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"17× trailing","type":"text","marks":[{"type":"bold"}]},{"text":" earnings","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"≈14× forward","type":"text","marks":[{"type":"bold"}]},{"text":" earnings (2025 consensus)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Management is guiding to ","type":"text"},{"text":"16 – 24 % revenue and profit growth","type":"text","marks":[{"type":"bold"}]},{"text":" for 2025, putting the PEG comfortably below 1. Return on invested capital sits north of 60 %. In short, the market has served up an Easter bargain.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bottom line","type":"text"}]},{"type":"paragraph","content":[{"text":"The noise around Lilly’s Phase 3 read-out has overshadowed the facts:","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Novo’s oral semaglutide is ahead in the queue","type":"text","marks":[{"type":"bold"}]},{"text":" and ","type":"text"},{"text":"more efficacious","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"It already carries a ","type":"text"},{"text":"cardiovascular benefit label","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The overall market is exploding; losing a few points of share still means outsized growth.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sometimes the hardest part of investing is ignoring the headlines and reading the data. I’ll happily add to my position while the crowd fixates on the wrong horse.","type":"text"}]},{"type":"horizontalRule"}]}'::jsonb,
  cover_image_url = '/covers/posts/novo-vs-lilly.webp',
  cover_image_alt = 'NVO vs LLY in large letters over a rising price line',
  tags = array['Healthcare', 'Stock Market']::text[],
  series = null,
  author = null,
  reading_minutes = 2
where slug = 'novo-nordisk-vs-eli-lilly-why-the-consensus-has-it-backwards-again';

