update public.posts set
  slug = 'is-google-stock-a-buy-in-2025',
  title = 'Alphabet (GOOGL): Is Google Stock a Buy in 2025?',
  excerpt = 'Many worry that AI will make Google search obsolete. Alphabet''s results say otherwise: search is stronger, Cloud is profitable and Gemini is everywhere, all at a forward P/E of about 16.',
  seo_description = 'Why Alphabet looks like a mispriced compounder in 2025: search, Cloud, YouTube, Waymo and a forward P/E well below its peers.',
  content = '{"type":"doc","content":[{"type":"stockSnapshot","attrs":{"company":"Alphabet","ticker":"GOOGL","exchange":"NASDAQ","verdict":"buy","currency":"USD","summary":"A mispriced compounder still valued like an ad-only business.","metrics":[{"label":"Forward P/E","value":"16.3x"},{"label":"Market cap","value":"US$1.86T"},{"label":"Free cash flow (TTM)","value":"US$74.9B"}],"price":"166.19"}},{"type":"paragraph","content":[{"text":"Although many worry that generative AI will render search obsolete, Alphabet is busy monetising the next wave of digital infrastructure—and that creates opportunity for investors.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Why Now Is an Attractive Entry Point","type":"text"}]},{"type":"paragraph","content":[{"text":"Despite reporting one of its strongest quarters ever, Alphabet still trades like a mature ad‐only business. In reality, it’s pivoted into a foundational AI‐infrastructure player, with consumer, enterprise and physical platforms all leveraging its unparalleled data moat.","type":"text"}]},{"type":"paragraph","content":[{"text":"Q1 2025 Highlights","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Revenue:","type":"text","marks":[{"type":"bold"}]},{"text":" US $90.2 billion (↑ 12% YoY)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"EPS:","type":"text","marks":[{"type":"bold"}]},{"text":" US $2.81 (↑ 49% YoY)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Operating Income:","type":"text","marks":[{"type":"bold"}]},{"text":" US $30.6 billion (↑ 20% YoY)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Operating Margin:","type":"text","marks":[{"type":"bold"}]},{"text":" 34% (vs 32% in Q1 2024)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Free Cash Flow:","type":"text","marks":[{"type":"bold"}]},{"text":" US $19 billion","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"CapEx:","type":"text","marks":[{"type":"bold"}]},{"text":" US $17.2 billion","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"TTM Free Cash Flow:","type":"text","marks":[{"type":"bold"}]},{"text":" US $74.9 billion","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"New Quarterly Dividend:","type":"text","marks":[{"type":"bold"}]},{"text":" US $0.21 per share","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Alphabet has also announced a US $70 billion share buy-back. These moves reflect confidence, not desperation.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Disciplined Leadership Under Sundar Pichai","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/is-google-stock-a-buy-in-2025/1.webp","caption":""}},{"type":"paragraph","content":[{"text":"Sundar Pichai has quietly shifted Alphabet from sprawling R&D to razor-sharp execution—without sacrificing long-term technology bets. In 2025, roughly US $75 billion of CapEx will target AI infrastructure (data centres, custom TPUs, networking), ensuring Alphabet stays ahead in model training and inference.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"AI as a Platform, Not Just a Feature","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/is-google-stock-a-buy-in-2025/2.webp","caption":""}},{"type":"paragraph","content":[{"text":"Rather than bolt on isolated AI tools, Alphabet is weaving its Gemini models into Search, Ads, Workspace (Gmail, Docs, Meet), YouTube and Cloud:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Search:","type":"text","marks":[{"type":"bold"}]},{"text":" Gemini now enhances over 100 million daily queries with richer answers and ad formats, boosting click-through rates in commercial categories.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Workspace:","type":"text","marks":[{"type":"bold"}]},{"text":" Contextual AI suggestions make Gmail, Docs and Meet stickier for both consumers and enterprises.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ads:","type":"text","marks":[{"type":"bold"}]},{"text":" Machine-learning-driven targeting raises relevance with lower user friction.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cloud:","type":"text","marks":[{"type":"bold"}]},{"text":" Vertex AI, BigQuery ML and Security AI Workbench turn Google Cloud into a profitable, AI-first rival to AWS.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"This deep integration leans on Google’s multi-decade trove of indexed web data, user queries and behavioural insights—an advantage no newcomer can match.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cloud: From Question Mark to Cash Engine","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Q1 Revenue:","type":"text","marks":[{"type":"bold"}]},{"text":" US $12.3 billion (↑ 28% YoY)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Profitability:","type":"text","marks":[{"type":"bold"}]},{"text":" Now sustainably profitable","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Major clients such as HSBC, Uber, GM, Shopify and Mayo Clinic underline that Google Cloud is critical infrastructure, not just an experiment.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/is-google-stock-a-buy-in-2025/3.webp","caption":""}},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Search: Reinforced, Not Eroded","type":"text"}]},{"type":"paragraph","content":[{"text":"Contrary to the bear case, search revenue hit US $50.7 billion in Q1 2025 (↑ 10% YoY) and continues to accelerate. Daily queries and mobile usage are at multi-year highs—now fuelled by AI-powered answers rather than replaced by them.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"YouTube’s Underappreciated Ecosystem","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ad Revenue:","type":"text","marks":[{"type":"bold"}]},{"text":" US $8.9 billion last quarter","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Shorts Views:","type":"text","marks":[{"type":"bold"}]},{"text":" 70 billion+ per day","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Premium Subscribers:","type":"text","marks":[{"type":"bold"}]},{"text":" 100 million+","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"YouTube spans creator monetisation, TV streaming, music and live commerce. With AI-driven recommendations, rights management and ad targeting, it deserves a standalone valuation north of US $475 billion—yet still trades at a blended multiple inside Alphabet.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Waymo: A Data-Rich Physical Platform","type":"text"}]},{"type":"paragraph","content":[{"text":"Waymo’s autonomous ride-hailing operates in San Francisco, Phoenix, Los Angeles and Austin—over 250,000 paid rides weekly. After raising US $5.6 billion in October 2024 (valuation ~US $45 billion), analysts forecast a US $305–850 billion valuation by 2030. Beyond cars, its real-world mapping, safety data and simulation feed back into Gemini, Maps and even in-vehicle ads.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/is-google-stock-a-buy-in-2025/4.webp","caption":""}},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"A Balance Sheet Built for Offence","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cash & Equivalents:","type":"text","marks":[{"type":"bold"}]},{"text":" US $95.3 billion","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Free Cash Flow (2024):","type":"text","marks":[{"type":"bold"}]},{"text":" US $75 billion","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Planned 2025 CapEx:","type":"text","marks":[{"type":"bold"}]},{"text":" US $75 billion","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"This financial firepower lets Alphabet lead strategic acquisitions, scale ahead of rivals and sustain long-horizon R&D without external financing.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Antitrust: Upside in a Break-Up Scenario","type":"text"}]},{"type":"paragraph","content":[{"text":"While DOJ action looms, a forced spin-out of Search, YouTube or Cloud could unlock hidden value—each segment would likely fetch a premium valuation independently. Even without a break-up, institutional investors are increasingly modelling these businesses separately, which may re-rate the stock.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/is-google-stock-a-buy-in-2025/5.webp","caption":""}},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Conclusion: A Mispriced Compounder","type":"text"}]},{"type":"paragraph","content":[{"text":"At a forward P/E of just 16.3×—well below peers like Amazon (29.5×) or Meta (23.4×)—Alphabet’s current market cap (~US $1.86 trillion) understates its AI-driven growth trajectory. Search is strengthening, Cloud is profitable, YouTube is scaling, Waymo is maturing and Gemini is everywhere. For long-term investors, the gap between perception and reality represents a rare opportunity.","type":"text"}]},{"type":"horizontalRule"}]}'::jsonb,
  cover_image_url = '/imported/is-google-stock-a-buy-in-2025/1.webp',
  cover_image_alt = 'Is Google Stock a Buy in 2025?',
  tags = array['AI', 'Technology']::text[],
  series = null,
  author = null,
  reading_minutes = 3
where slug = 'is-google-stock-a-buy-in-2025';

update public.posts set
  slug = 'meta-in-2030-from-ads-to-ai-infrastructure-powerhouse',
  title = 'Meta (META) in 2030: From Ads to AI Infrastructure Powerhouse',
  excerpt = 'Most people still see Meta as a social media company. Behind the scenes it is turning into an AI infrastructure business, and even the gloomiest 2030 scenario points to steady returns from today''s price.',
  seo_description = 'How Meta is turning into an AI infrastructure company, and what its earnings and valuation could look like by 2030.',
  content = '{"type":"doc","content":[{"type":"stockSnapshot","attrs":{"company":"Meta Platforms","ticker":"META","exchange":"NASDAQ","verdict":"buy","currency":"USD","summary":"Valued on its past as an ad business, building a future in AI infrastructure.","metrics":[{"label":"Forward P/E","value":"26x"},{"label":"Market cap","value":"US$1.28T"},{"label":"Returned to owners","value":"~US$70B a year"}],"price":"682.87"}},{"type":"paragraph","content":[{"text":"Why Meta’s future looks very different from its past","type":"text","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Meta’s Transformation Is Already Underway","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/meta-in-2030-from-ads-to-ai-infrastructure-powerhouse/1.webp","caption":""}},{"type":"paragraph","content":[{"text":"Most people still think of Meta as just a social media company. But under the surface, it’s rapidly evolving into something much bigger. Over the past couple of years, Meta has been quietly but aggressively reshaping its internal structure—cutting costs, shifting priorities, and pouring resources into building a massive AI infrastructure backbone.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"From Social Growth Engine to AI Power Platform","type":"text"}]},{"type":"paragraph","content":[{"text":"Between 2012 and 2020, Meta mastered mobile monetisation through Facebook, Instagram, and WhatsApp. But privacy changes and rising regulation slowed the ad machine. Instead of seeing this as the end, Meta used it as a springboard—downsizing projects and doubling down on its technical strengths. Even the widely mocked metaverse push showed that Meta’s leadership isn’t afraid to bet big on the future.","type":"text"}]},{"type":"paragraph","content":[{"text":"That mindset is now fuelling its pivot to AI tools, platforms, and internal systems—with visible results.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/meta-in-2030-from-ads-to-ai-infrastructure-powerhouse/2.webp","caption":""}},{"type":"heading","attrs":{"level":2},"content":[{"text":"Financial Muscle Behind the Shift","type":"text"}]},{"type":"paragraph","content":[{"text":"Meta is still a financial juggernaut. In Q1 2025, it pulled in $42.3 billion in revenue, with a net margin over 32%. And it’s investing aggressively: up to $72 billion in capital spending this year, mostly on AI infrastructure. This isn’t wasteful spending—it’s core to building scalable, cost-efficient AI systems.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yet, Meta is still rewarding shareholders—returning nearly $70 billion via buybacks and dividends over the past year.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"The Scale AI Acquisition: A Game-Changer","type":"text"}]},{"type":"paragraph","content":[{"text":"In June 2025, Meta bought a majority stake in Scale AI for $14.8 billion. This gave it access to top-tier datasets, advanced testing systems, and fine-tuning capabilities. Scale’s founder, Alex Wang, now leads Meta’s AI safety and alignment efforts. The acquisition isn’t just about tools—it’s about full-stack integration, from data to deployment, giving Meta unmatched control over cost, iteration, and speed.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"LLaMA and Open-Source Advantage","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/meta-in-2030-from-ads-to-ai-infrastructure-powerhouse/3.webp","caption":""}},{"type":"paragraph","content":[{"text":"Meta’s LLaMA models are becoming some of the most widely used open-source language models globally. While proprietary models like GPT-4o may still lead in benchmarks, LLaMA is already embedded into Meta’s own apps—Messenger, WhatsApp, Instagram—and is widely adopted by external developers.","type":"text"}]},{"type":"paragraph","content":[{"text":"Interestingly, Meta still uses external models like Claude for internal tools when it makes sense. This pragmatic approach puts performance over ideology.","type":"text"}]},{"type":"paragraph","content":[{"text":"By open-sourcing LLaMA, Meta also builds developer trust and transparency—key advantages as regulations tighten around AI explainability.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Monetisation Without Needing New Users","type":"text"}]},{"type":"paragraph","content":[{"text":"Meta continues to reach over 3 billion users monthly across its platforms. This gives it a massive edge in applying AI directly into products people already use.","type":"text"}]},{"type":"paragraph","content":[{"text":"New revenue streams are appearing: Reels uses AI to improve content discovery; ad creation is being automated with generative tools; and WhatsApp/Messenger are integrating smarter business APIs and chatbots. These tools aren’t moonshots—they’re integrated into everyday use, increasing revenue per user without needing more users.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Zuckerberg’s Role in Meta’s Evolution","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/meta-in-2030-from-ads-to-ai-infrastructure-powerhouse/4.webp","caption":""}},{"type":"paragraph","content":[{"text":"Mark Zuckerberg’s influence is still central. With control over voting shares, he can make bold long-term bets without being swayed by short-term investor pressure. While not every initiative has succeeded (e.g. the metaverse), his ability to pivot Meta ahead of industry shifts remains unmatched. The AI transition reflects this same boldness, only this time, it’s more grounded and infrastructure-led.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"The Data Advantage","type":"text"}]},{"type":"paragraph","content":[{"text":"AI runs on data—and Meta has more of it than almost anyone. It processes billions of interactions across text, video, voice, and images every day. These real-time, highly contextual feedback loops help train and refine its models in ways most companies can’t match. That means better personalisation, monetisation, and defensibility.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Valuing Meta’s Future, Not Its Past","type":"text"}]},{"type":"paragraph","content":[{"text":"As of June 2025, Meta trades at a forward P/E of 26x and a $1.28 trillion valuation—still largely based on its ad business legacy. But this overlooks the depth of its AI investments and growing monetisation layers.","type":"text"}]},{"type":"paragraph","content":[{"text":"Here’s what Meta’s earnings might look like by 2030, depending on different scenarios:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Scenario","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Revenue (B)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Net Margin","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Net Income (B)","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Valuation Range (23x–35x P/E)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bear","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"210","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"30%","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"63","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$1.45T – $2.21T","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Base","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"245","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"33%","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"80.85","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$1.86T – $2.83T","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bull","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"260","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"34%","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"88.4","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$2.03T – $3.09T","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Stretch","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"300","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"37%","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"111","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$2.55T – $3.88T","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Even in the most conservative scenario, Meta is positioned for steady returns. The base and bull cases suggest annualised growth between 8% and 13%, driven by AI adoption, developer tools, and productivity boosts.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Final Thought: A New Meta Is Emerging","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"/imported/meta-in-2030-from-ads-to-ai-infrastructure-powerhouse/5.webp","caption":""}},{"type":"paragraph","content":[{"text":"Meta is no longer just an ad-driven social network—it’s becoming a foundational platform for the AI era. With world-class data, full-stack infrastructure, and broad user reach, it has all the pieces to lead the next decade in tech.","type":"text"}]},{"type":"paragraph","content":[{"text":"Those who keep viewing Meta through the lens of its past might miss the bigger picture. The real opportunity lies in what Meta is building now, and what’s still to come.","type":"text"}]}]}'::jsonb,
  cover_image_url = '/imported/meta-in-2030-from-ads-to-ai-infrastructure-powerhouse/1.webp',
