update public.posts set
  slug = 'agora-api-the-micro-cap-nobodys-watching',
  title = 'Agora (API): The Micro-Cap Nobody’s Watching',
  excerpt = 'Agora''s share price has fallen about 95% and its accounts are full of one-off write-downs. Underneath, it holds more cash than its entire market value, has no debt, still produces free cash flow and is buying back its own shares.',
  seo_description = 'Agora (API) holds more cash than its market value. How impairments hide a cash-rich business, and the catalysts that could unlock it.',
  content = '{"type":"doc","content":[{"type":"stockSnapshot","attrs":{"company":"Agora, Inc.","ticker":"API","exchange":"NASDAQ","verdict":"buy","currency":"USD","summary":"A cash-rich micro-cap hidden behind accounting noise. For patient investors.","metrics":[{"label":"Market cap","value":"~US$167M"},{"label":"Cash","value":"US$286M"},{"label":"Debt","value":"US$0"}],"price":"4.04"}},{"type":"paragraph","content":[{"text":"How impairments, restructuring, and aggressive buybacks could unlock value in this real-time engagement pioneer","type":"text","marks":[{"type":"bold"}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"TL;DR","type":"text"}]},{"type":"paragraph","content":[{"text":"Key Metrics (as of Q1 2025):","type":"text","marks":[{"type":"bold"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Metric","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Value","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Market Cap","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"~$167 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Cash Position","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$286.3 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Total Debt","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"TTM Net Income (with impairments)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"-$63.8 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"TTM FCF (excluding impairments)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$18.6 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Share Buyback Program","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$50 million authorised ($40.5 million remaining)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"1-month performance","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"+32%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"EV/FCF","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"-6.4 (i.e. negative EV due to high net cash)","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Agora (API) shows how accounting noise and a battered growth narrative can obscure hidden value. Its stock has crashed ~95% from 2021 highs, but it now trades below net cash. Large impairment charges and restructuring costs hide the fact that it’s still cash flow positive, with share buybacks and a balance sheet that could outlast years of market negativity.","type":"text"}]},{"type":"paragraph","content":[{"text":"This is the type of micro-cap that could double or triple quickly if sentiment flips.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"The Business: More Than Just Video Calls","type":"text"}]},{"type":"paragraph","content":[{"text":"Agora offers programmable APIs powering:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Real-time voice/video chat","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Interactive livestreaming","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Low-latency broadcasting","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"AI-driven audio/video processing","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Their customers include social apps, gaming platforms, e-commerce streaming, and online education services.","type":"text"}]},{"type":"paragraph","content":[{"text":"Why the collapse?","type":"text","marks":[{"type":"bold"}]},{"text":" Pandemic tailwinds reversed. Growth slowed. Agora’s top-line shrank from $175 million in 2021 to ~$137 million in 2024. Also, they recorded huge impairments from a failed acquisition:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"EasyChat (acquired 2021):","type":"text","marks":[{"type":"bold"}]},{"text":" Agora paid ~$110 million for a Chinese social app aiming to boost revenue in China. The government’s tech crackdown and declining app usage forced Agora to impair nearly the entire investment.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"This has left the stock battered and trading at absurdly cheap multiples.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"The Hidden Value Thesis","type":"text"}]},{"type":"paragraph","content":[{"text":"Two key drivers spark my interest:","type":"text","marks":[{"type":"bold"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Massive net cash position","type":"text","marks":[{"type":"bold"}]},{"text":" – Agora holds ~$286 million cash and no debt, exceeding its entire market cap.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Core business still generates cash","type":"text","marks":[{"type":"bold"}]},{"text":" – TTM operating cash flow remains positive even after impairments and restructuring.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Let’s break that down.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Catalyst #1: The Impairment Charges Are Done","type":"text"}]},{"type":"paragraph","content":[{"text":"The $105.7 Million EasyChat Mistake","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"From their latest filings:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"“During 2023, the Company determined that the EasyChat unit’s carrying value was no longer recoverable due to lower usage, monetisation challenges, and regulatory uncertainty.”","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Impairment summary:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Type","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Amount","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Goodwill impairment","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$45.2 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Intangibles impairment","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$60.5 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Total impairment","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$105.7 million","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"These impairments smashed net income:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"2023 Net Income: ","type":"text"},{"text":"-$89.2 million","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"2024 Net Income: ","type":"text"},{"text":"-$63.8 million","type":"text","marks":[{"type":"bold"}]}]}]}]},{"type":"paragraph","content":[{"text":"Yet cash flow remains positive. These non-cash write-downs are flowing through the income statement, obscuring the true operating picture.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Catalyst #2: Aggressive Share Buybacks","type":"text"}]},{"type":"paragraph","content":[{"text":"Agora authorised a ","type":"text"},{"text":"$50 million share repurchase program","type":"text","marks":[{"type":"bold"}]},{"text":" in December 2024. They’ve already deployed ~19% of that:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Buybacks","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Value","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Total authorised","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$50 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Spent to date","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$9.5 million","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Remaining","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$40.5 million","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"At current prices, even modest repurchases are highly accretive. For instance, with a ~$167 million market cap, the authorised $50M buyback could theoretically retire nearly ","type":"text"},{"text":"30% of the float","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Management explicitly stated in earnings calls:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"“We believe our current market valuation does not reflect our cash position or long-term prospects.”","type":"text"}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Catalyst #3: Cost Restructuring","type":"text"}]},{"type":"paragraph","content":[{"text":"Agora launched restructuring in early 2025:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Target Savings:","type":"text","marks":[{"type":"bold"}]},{"text":" $10–$12 million annually","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Timeline:","type":"text","marks":[{"type":"bold"}]},{"text":" Full impact by late 2025","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Focus:","type":"text","marks":[{"type":"bold"}]},{"text":" Headcount reductions, data centre optimisation, lower sales & marketing","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Even modest savings could boost free cash flow significantly:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Scenario","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Potential Annual FCF Increase","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Low-end savings ($10M)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"+$10M","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"High-end savings ($12M)","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"+$12M","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"For a company with a $167 million market cap, that’s huge.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"The Business Performance Reality","type":"text"}]},{"type":"paragraph","content":[{"text":"Despite impairments, Agora still has a healthy core business:","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Metric","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"FY 2023","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"FY 2024","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Revenue","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$140.8M","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$137.1M","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Gross Margin","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"60.2%","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"62.8%","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Operating Cash Flow","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$16.2M","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$18.6M","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"What’s working:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Solid gross margins remain ~60%","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"New AI video/audio SDKs gaining traction","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"International growth ex-China stabilising","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"What’s not:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Chinese revenue declined ~40% YoY","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Post-COVID normalisation reduced demand for video APIs","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Negative headlines keep investors away","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Valuation","type":"text"}]},{"type":"paragraph","content":[{"text":"Agora has an unusual profile: ","type":"text"},{"text":"its net cash exceeds its market cap.","type":"text","marks":[{"type":"bold"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Metric","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Value","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Market Cap","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$167M","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Net Cash","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"$286M","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Enterprise Value","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"-$119M","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"This implies a negative EV","type":"text","marks":[{"type":"bold"}]},{"text":", meaning you’re getting the business for free—and getting paid ~$119 million to own it.","type":"text"}]},{"type":"paragraph","content":[{"text":"Here’s a quick valuation look:","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bear Case","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"FCF = $10M","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"EV = $0 (net cash supports valuation)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Implied P/FCF: 16.7× → ~$2.12/share fair value","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Base Case","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"FCF = $18M (TTM)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Modest growth: 5%","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"EV/FCF = 10× → $180M EV","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fair value: ~$4.60/share (+175%)","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Bull Case","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"FCF = $28M (includes $10M restructuring savings)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Growth = 8% CAGR","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"EV/FCF = 12× → $336M EV","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fair value: ~$7.22/share (+330%)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Even conservative estimates suggest ","type":"text"},{"text":"fair value ~2–3× above current price","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"Why This Setup Interests Me","type":"text"}]},{"type":"paragraph","content":[{"text":"This is the perfect micro-cap mispricing:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Massive net cash","type":"text","marks":[{"type":"bold"}]},{"text":" shields downside.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Accounting impairments","type":"text","marks":[{"type":"bold"}]},{"text":" obscure positive cash flow.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The business is ","type":"text"},{"text":"still profitable on a cash basis.","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ongoing buybacks provide a strong floor.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"While there’s no guarantee the core business will reaccelerate, the cash alone provides a margin of safety.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"text":"The Bottom Line","type":"text"}]},{"type":"paragraph","content":[{"text":"Agora is trading below its net cash, an anomaly rarely seen in public markets. Like ZDGE, it’s a textbook case where ","type":"text"},{"text":"accounting noise and investor fatigue hide real value.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"It’s not risk-free:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Chinese exposure remains a political/regulatory overhang.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Revenue has stagnated.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The EasyChat acquisition showed questionable capital allocation.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"But for those willing to dig through the numbers, Agora might be a hidden gem.","type":"text"}]},{"type":"paragraph","content":[{"text":"At worst, you’re buying cash at a discount. At best, you’re getting a profitable SaaS business thrown in for free.","type":"text","marks":[{"type":"bold"}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":3},"content":[{"text":"Key Takeaway","type":"text"}]},{"type":"paragraph","content":[{"text":"This is the type of setup I love in micro-caps:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"“Negative EV. Positive cash flow. Management buying shares. Market ignoring it.”","type":"text"}]}]},{"type":"paragraph","content":[{"text":"It’s risky. But the risk-reward looks compelling for those with patience.","type":"text"}]},{"type":"horizontalRule"},{"type":"horizontalRule"},{"type":"paragraph","content":[{"text":"Sources:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Agora, Inc. SEC filings (10-K, 10-Q)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Yahoo Finance","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"TradingView","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Company earnings calls","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Personal analysis","type":"text"}]}]}]}]}'::jsonb,
